    def fetch_account_id(self, params={}, _ccxtTypesImportStr: Str = None) -> Str:
        fromParams = self.safe_bool_2(params, 'isFuture', 'future', None)
        isFuture = False
        if fromParams is not None:
            isFuture = fromParams
        else:
            t = self.safe_string_2(self.options, 'defaultType', 'defaultSubType', '')
            isFuture = (t == 'swap' or t == 'future')
        if isFuture:
            raw = self.fapiPrivateV3GetBalance(params)
            row = isinstance(raw, list) and raw[0] if len(raw) else {}
            alias = self.safe_string(row, 'accountAlias')
            if alias is None:
                raise ExchangeError(self.id + ' missing futures accountAlias')
            return alias
        bal = self.fetch_balance(params)
        info = self.safe_dict(bal, 'info')
        uid = self.safe_string(info, 'uid')
        if uid is None:
            raise ExchangeError(self.id + ' missing spot uid')
        return uid

    def is_authenticated_request(self, url: Str, method: Str, headers: dict, body, _ccxtTypesImportStr: Str = None) -> Bool:
        return self.ob_is_authenticated_request(url, method, headers, body, 'urlBodySignature', {})

    def parse_order(self, order: dict, market: Market = None) -> Order:
        # override the standard parseOrder to apply OctoBot's BinanceCCXTAdapter.fix_order logic:
        # 1) call the standard parseOrder
        # 2) rewrite "PENDING_NEW" status as "open"(binance returns self for old open orders)
        # 3) re-tag stop / take-profit orders that ccxt does not flag, force their price
        #    to the trigger price and compute triggerAbove from the side
        parsed = super(ob_binance, self).parse_order(order, market)
        if self.safe_string(parsed, 'status') == 'PENDING_NEW':
            # PENDING_NEW orders are old orders on binance and should be considered
            parsed['status'] = 'open'
        self.adapt_order_type(parsed)
        return parsed

    def parse_trade(self, trade: dict, market: Market = None) -> Trade:
        # override the standard parseTrade to apply OctoBot's BinanceCCXTAdapter.fix_trades:
        # every trade returned by the exchange is a closed(executed) fill, force the status
        parsed = super(ob_binance, self).parse_trade(trade, market)
        parsed['status'] = 'closed'
        return parsed

    def parse_funding_rate(self, contract, market: Market = None) -> FundingRate:
        # override the standard parseFundingRate to apply OctoBot's BinanceCCXTAdapter.parse_funding_rate:
        # binance does not provide the previous funding time, derive it from the upcoming funding
        # timestamp(ccxt's fundingTimestamp, taken from raw nextFundingTime) by subtracting
        # the default 8h funding interval
        parsed = super(ob_binance, self).parse_funding_rate(contract, market)
        fundingTimestamp = self.safe_integer(parsed, 'fundingTimestamp')
        if fundingTimestamp is not None:
            intervalMs = 8 * 60 * 60 * 1000
            previousFundingTimestamp = max(fundingTimestamp - intervalMs, 0)
            parsed['previousFundingTimestamp'] = previousFundingTimestamp
            parsed['previousFundingDatetime'] = self.iso8601(previousFundingTimestamp)
        return parsed

    def adapt_order_type(self, parsed: dict) -> dict:
        stopOrders = [
            'stop_market', 'stop',              # futures
            'stop_loss', 'stop_loss_limit',     # spot
        ]
        takeProfitOrders = [
            'take_profit_market', 'take_profit_limit',  # futures
            'take_profit',                              # spot
        ]
        orderInfo = self.safe_dict(parsed, 'info', {})
        rawType = self.safe_string_lower_2(orderInfo, 'type', 'orderType', '')
        isStop = self.in_array(rawType, stopOrders)
        isTp = self.in_array(rawType, takeProfitOrders)
        if not isStop and not isTp:
            return parsed
        triggerPrice = self.safe_number(parsed, 'triggerPrice')
        if triggerPrice is None or triggerPrice == 0:
            self.log(
                'ob_binance.parseOrder',
                'Unknown binance order: stop order with no trigger price, order: ' + self.json(parsed)
            )
            return parsed
        selling = self.safe_string_lower(parsed, 'side') == 'sell'
        updatedType: Str = 'unknown'
        triggerAbove = False
        if isStop:
            updatedType = 'stop_loss'
            # force price to trigger price
            parsed['price'] = triggerPrice
            triggerAbove = not selling    # sell stop loss triggers when price is lower than target
        elif isTp:
            # take profits are not yet handled: consider them orders
            updatedType = 'limit'      # waiting for TP handling
            if not parsed['price']:
                parsed['price'] = triggerPrice     # waiting for TP handling
            triggerAbove = selling     # sell take profit triggers when price is higher than target
        # stop loss and take profits are not tagged by ccxt, force it
        parsed['type'] = updatedType
        parsed['triggerAbove'] = triggerAbove
        return parsed
